using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
// Explicit attenuation is applied to the generated PCM as well as the spatial source.
// This prevents a procedural filter from leaving a distance-independent background bed.
public sealed class RoadEngineAudio:MonoBehaviour {
 public FinchVehicle Car;public static bool AllowBackgroundForTests;public float AudibleGain{get;private set;}public const float Range=52;
 static int budgetFrame=-1;static Vector3 budgetPoint;static float mixGain=1;static readonly RoadEngineAudio[] closest=new RoadEngineAudio[6];static readonly float[] closestDistances=new float[6];static int nextVoiceId;int voiceId;static readonly List<RoadEngineAudio> voices=new List<RoadEngineAudio>();readonly RaycastHit[] hits=new RaycastHit[12];
 WorkshopAudioVoice voice;AudioClip clip;AudioSource source;AudioLowPassFilter lowPass;AudioListener listener;float occlusion=1,rayTimer,silentFor;
 public static float DistanceGain(float meters){float t=Mathf.Clamp01((meters-2)/(Range-2));return (1-t)*(1-t);}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]static void Reset(){voices.Clear();budgetFrame=-1;nextVoiceId=0;AllowBackgroundForTests=false;}
 void Start(){voiceId=++nextVoiceId;voices.Add(this);var g=new GameObject("NPC engine | distance gated spatial voice");g.transform.SetParent(transform,false);source=g.AddComponent<AudioSource>();source.spatialBlend=1;source.minDistance=2;source.maxDistance=Range;source.rolloffMode=AudioRolloffMode.Linear;source.dopplerLevel=.25f;source.volume=.45f;source.priority=160;source.loop=true;int rate=AudioSettings.outputSampleRate;clip=AudioClip.Create("NPC original engine",rate,1,rate,false);source.clip=clip;voice=g.AddComponent<WorkshopAudioVoice>();voice.rate=rate;voice.master=0;voice.explicitPan=true;lowPass=g.AddComponent<AudioLowPassFilter>();lowPass.cutoffFrequency=9000;source.Play();}
 void LateUpdate(){if(voice==null||Car?.Engine==null)return;if(listener==null||!listener.isActiveAndEnabled){listener=null;foreach(var ear in FindObjectsByType<AudioListener>(FindObjectsSortMode.None))if(ear.isActiveAndEnabled){listener=ear;break;}}Vector3 earPoint=listener==null?transform.position+Vector3.up*10000:listener.transform.position;float distance=Vector3.Distance(earPoint,transform.position);UpdateBudget(earPoint);bool selected=false;for(int n=0;n<closest.Length;n++)if(closest[n]==this)selected=true;rayTimer-=Time.unscaledDeltaTime;if(distance<Range&&rayTimer<=0){rayTimer=.16f;occlusion=1;var end=transform.position+Vector3.up;var delta=end-earPoint;int count=Physics.RaycastNonAlloc(earPoint,delta.normalized,hits,delta.magnitude,~((1<<28)|(1<<29)|(1<<31)),QueryTriggerInteraction.Ignore);for(int i=0;i<count;i++)if(hits[i].collider.GetComponentInParent<FinchVehicle>()==null&&hits[i].normal.y<.8f){occlusion=.22f;break;}}float wanted=listener!=null&&selected?DistanceGain(distance)*occlusion*mixGain:0;voice.pan=listener==null?0:Vector3.Dot((transform.position-earPoint).normalized,listener.transform.right);ApplySignal(wanted,Application.isFocused||Debug.isDebugBuild&&AllowBackgroundForTests);lowPass.cutoffFrequency=Mathf.Lerp(lowPass.cutoffFrequency,occlusion<1?1300:9000,1-Mathf.Exp(-Time.unscaledDeltaTime*9));if(wanted<=0||voice.master<=0)silentFor+=Time.unscaledDeltaTime;else silentFor=0;if(silentFor>.35f){if(source.isPlaying)source.Pause();}else if(!source.isPlaying)source.UnPause();}
 static void UpdateBudget(Vector3 point){if(budgetFrame==Time.frameCount&&(point-budgetPoint).sqrMagnitude<.001f)return;budgetFrame=Time.frameCount;budgetPoint=point;for(int i=0;i<6;i++){closest[i]=null;closestDistances[i]=float.MaxValue;}foreach(var candidate in voices){if(candidate==null||candidate.Car?.Engine==null)continue;float d=(candidate.transform.position-point).sqrMagnitude;if(d>=Range*Range)continue;for(int i=0;i<6;i++)if(d<closestDistances[i]-.001f||Mathf.Abs(d-closestDistances[i])<.001f&&(closest[i]==null||candidate.voiceId<closest[i].voiceId)){for(int n=5;n>i;n--){closest[n]=closest[n-1];closestDistances[n]=closestDistances[n-1];}closest[i]=candidate;closestDistances[i]=d;break;}}float energy=0;for(int i=0;i<6;i++)if(closest[i]!=null){float gain=DistanceGain(Mathf.Sqrt(closestDistances[i]));energy+=gain*gain;}mixGain=1/Mathf.Sqrt(Mathf.Max(1,energy));}
 void ApplySignal(float gain,bool audible){AudibleGain=audible?Mathf.Clamp01(gain):0;voice.hz=Car.Engine.Rpm/30;voice.cylinders=VehicleLineup.Cylinders(string.IsNullOrEmpty(Car.EngineModelId)?Car.PowertrainCarId:Car.EngineModelId);voice.engineLoad=Car.Throttle;voice.volume=.010f+.032f*Car.Throttle;voice.master=AudibleGain;}
 void OnDestroy(){voices.Remove(this);if(source!=null)source.Stop();if(clip!=null)Destroy(clip);}
}
}
